    "AdminComment" text,
    "VerifiedByUserId" integer,
    "UploadedAt" timestamp with time zone NOT NULL,
    "VerifiedAt" timestamp with time zone,
    CONSTRAINT "PK_DriverApplicationDocuments" PRIMARY KEY ("DriverApplicationDocumentId"),
    CONSTRAINT "FK_DriverApplicationDocuments_DriverApplications_DriverApplica~" FOREIGN KEY ("DriverApplicationId") REFERENCES "DriverApplications" ("DriverApplicationId") ON DELETE CASCADE,
    CONSTRAINT "FK_DriverApplicationDocuments_Users_VerifiedByUserId" FOREIGN KEY ("VerifiedByUserId") REFERENCES "Users" ("UserId") ON DELETE SET NULL
);

